// Cases from `check_mention`, `check_hashtag`, `check_cashtag`, `check_bank_card_number`,
// `check_tg_url`, `check_url` and `check_is_email_address` in TDLib's `test/message_entities.cpp` at
// commit bc9c263e2bfee06aaab41e82db51a103376030bc. Each case lists the text and what TDLib finds in
// it; URL cases list URLs, then email addresses. Email address checks also combine every user part
// with every domain, as that file does.

/** A text and the spans of it that a finder finds, in order. */
export type TdlibFindCase = readonly [text: string, expected: readonly string[]];

